/**
 * Minimal valid image fixtures for E2E upload tests.
 *
 * Each constant is a Buffer containing the smallest valid encoding of its
 * format that passes SixLabors.ImageSharp's decoder (used by the backend to
 * process uploads before storage).
 *
 * The PNG / JPEG / WebP bytes were generated by SixLabors.ImageSharp 3.x
 * (see /tmp/gen-images/).  The GIF is the well-known 1×1 transparent GIF89a
 * that also passes ImageSharp.  Regenerate if you need to update them.
 */

/**
 * 1 × 1 RGBA PNG, 84 bytes.
 * Generated by SixLabors.ImageSharp 3.x — passes the CRC checks that the
 * original hand-crafted fixture did not.
 */
export const MINIMAL_PNG: Buffer = Buffer.from(
  '89504e470d0a1a0a0000000d4948445200000001000000010806' +
  '0000001f15c489000000097048597300000ec400000ec401952b' +
  '0e1b0000000b49444154789c63f90f04000a0f04016cc637a700' +
  '00000049454e44ae426082',
  'hex',
)

