/**
 * 1 × 1 transparent GIF 89a, 35 bytes.
 * Magic: 47 49 46 38 39 61 ("GIF89a").
 * This is the well-known minimal GIF and passes SixLabors.ImageSharp.
 */
export const MINIMAL_GIF: Buffer = Buffer.from(
  'R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7',
  'base64',
)

/**
 * 1 × 1 lossy WebP, ~54 bytes.
 * Generated by SixLabors.ImageSharp 3.x.
 * Magic: 52 49 46 46 ... 57 45 42 50 ("RIFF…WEBP").
 */
export const MINIMAL_WEBP: Buffer = Buffer.from(
  'UklGRi4AAABXRUJQVlA4ICIAAABQAgCdASoBAAEALmk0mk0kJCQkBABoS0gABuAA/vuUAAAA',
  'base64',
)

/** Small fake MP4 ftyp-box prefix — not a playable video, but has MP4 magic bytes. */
export const FAKE_MP4: Buffer = Buffer.from(
  '0000001866747970 6d703432 00000000 6d703432 69736f6d'.replace(/\s/g, ''),
  'hex',
)

/** 3 bytes of garbage — useful for wrong-format negative tests. */
export const GARBAGE_BYTES: Buffer = Buffer.from([0x00, 0x01, 0x02])
